#include <algorithm>
#include <cmath>

struct Vector3 { float x, y, z; };

namespace { constexpr float Rad{ 3.14159265358979f / 180.0f }; }

Vector3 lookDirection(float yaw, float pitch)
{
    const float y{ yaw * Rad }, p{ pitch * Rad };
    return { std::cos(p) * std::sin(y), std::sin(p), std::cos(p) * std::cos(y) };
}

float clampPitch(float pitch) { return std::clamp(pitch, -89.0f, 89.0f); }

float wrapYaw(float yaw)
{
    float w{ std::fmod(yaw, 360.0f) };
    if (w < 0) w += 360.0f;
    if (w >= 360.0f) w -= 360.0f;
    return w;
}

Vector3 wishDirection(float yaw, bool forward, bool back, bool left, bool right)
{
    const float y{ yaw * Rad };
    const Vector3 f{ std::sin(y), 0, std::cos(y) }, r{ -std::cos(y), 0, std::sin(y) };
    const float fw{ static_cast<float>(forward) - static_cast<float>(back) };
    const float rt{ static_cast<float>(right) - static_cast<float>(left) };
    Vector3 w{ f.x * fw + r.x * rt, 0, f.z * fw + r.z * rt };
    const float len{ std::sqrt(w.x * w.x + w.z * w.z) };
    if (len > 0) { w.x /= len; w.z /= len; }
    return w;
}

Vector3 orbitPosition(Vector3 target, float yaw, float pitch, float distance)
{
    const Vector3 d{ lookDirection(yaw, pitch) };
    return { target.x - d.x * distance, target.y - d.y * distance, target.z - d.z * distance };
}

unitTests:
bool near3(Vector3 v, float x, float y, float z) { return std::fabs(v.x - x) < 1e-3f && std::fabs(v.y - y) < 1e-3f && std::fabs(v.z - z) < 1e-3f; }
TEST("looking") { CHECK(near3(lookDirection(0, 0), 0, 0, 1)); CHECK(near3(lookDirection(90, 0), 1, 0, 0)); CHECK(near3(lookDirection(0, 90), 0, 1, 0)); CHECK(near3(lookDirection(180, -30), 0, -0.5f, -0.8660f)); }
TEST("limits") { CHECK_NEAR(clampPitch(120), 89.0, 1e-6); CHECK_NEAR(clampPitch(-95), -89.0, 1e-6); CHECK_NEAR(clampPitch(10), 10.0, 1e-6); CHECK_NEAR(wrapYaw(370), 10.0, 1e-4); CHECK_NEAR(wrapYaw(-90), 270.0, 1e-4); CHECK_NEAR(wrapYaw(720), 0.0, 1e-4); }
TEST("walking") {
    CHECK(near3(wishDirection(0, true, false, false, false), 0, 0, 1)); CHECK(near3(wishDirection(0, false, false, false, true), -1, 0, 0));
    CHECK(near3(wishDirection(0, true, false, false, true), -0.70711f, 0, 0.70711f)); CHECK(near3(wishDirection(90, true, false, false, false), 1, 0, 0));
    CHECK(near3(wishDirection(45, true, true, true, true), 0, 0, 0));
}
TEST("orbit camera") { CHECK(near3(orbitPosition({ 0, 1.5f, 0 }, 0, -30, 4), 0, 3.5f, -3.4641f)); CHECK(near3(orbitPosition({ 2, 0, 2 }, 90, 0, 3), -1, 0, 2)); }

